#!/usr/bin/env python3
"""コンテナの中で、ワーカーのテストを実行する。使い方: repro.py <review-triage のコピー> <TERM|HUP|INT> <回数> <sync|nosync>
sync のとき、os.killpg を置き換え、ワーカーの子孫で ps -A が実行中になってからシグナルを送る。"""
import os, signal, subprocess, sys, threading, time, unittest

base, signame, count, mode = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4]
sys.path.insert(0, os.path.join(base, "tests"))
import test_review_loop_worker as m

SIG = {"TERM": (signal.SIGTERM, 143), "HUP": (signal.SIGHUP, 129), "INT": (signal.SIGINT, 130)}[signame]
m.TestInterruptPhases.SIGNALS = (SIG,)
real_killpg = os.killpg
hits = []

def children(pid):
    out = []
    try:
        for tid in os.listdir(f"/proc/{pid}/task"):
            with open(f"/proc/{pid}/task/{tid}/children") as f:
                out += [int(x) for x in f.read().split()]
    except OSError:
        pass
    return out

def find_ps(root):
    stack, seen = [root], set()
    while stack:
        pid = stack.pop()
        if pid in seen:
            continue
        seen.add(pid)
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as f:
                c = f.read().split(b"\0")
            if c[0] == b"ps" and b"-A" in c:
                return pid
        except OSError:
            pass
        stack += children(pid)
    return None

def dump_later(pgid, delay, label):
    def run():
        time.sleep(delay)
        r = subprocess.run("ps -eo pid,ppid,pgid,stat,etimes,args | cut -c1-100 | grep -E 'review-loop-worker|bin/claude|python3' | grep -vE 'repro|grep'", shell=True, capture_output=True, text=True)
        print(f"--- シグナルの {delay} 秒後のプロセス ({label})\n{r.stdout}", flush=True)
    threading.Thread(target=run, daemon=True).start()

def killpg(pgid, sig):
    if sig in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT) and mode == "sync":
        end = time.time() + 5
        found = None
        while time.time() < end and found is None:
            found = find_ps(pgid)
        if found is not None:
            e = time.perf_counter() + 0.002  # ps が exec してシグナルハンドラを設定するまで
            while time.perf_counter() < e:
                pass
        hits.append(found)
    if sig in (signal.SIGTERM, signal.SIGHUP, signal.SIGINT):
        dump_later(pgid, 12, signal.Signals(sig).name)
    return real_killpg(pgid, sig)

os.killpg = killpg

if mode == "sync":
    # ps -A の実行時間を、CI のようにプロセスが多い環境に近づける
    dummies = [subprocess.Popen(["sleep", "3000"]) for _ in range(300)]

ok = bad = 0
for i in range(count):
    t0 = time.time()
    res = unittest.TestResult()
    m.TestInterruptPhases("test_interrupt_while_stopping_reviewer_after_timeout").run(res)
    passed = res.wasSuccessful()
    ok += passed
    bad += not passed
    last = ""
    for _, tb in res.errors + res.failures:
        last = tb.strip().splitlines()[-1][:170]
    print(f"{signame} {mode} {i+1}: {'成功' if passed else '失敗'} ({time.time()-t0:.1f} 秒) {last}", flush=True)
print(f"== {signame} {mode}: 成功 {ok} / 失敗 {bad} (ps の実行中に送れた回数 {sum(h is not None for h in hits)}/{len(hits)})", flush=True)
os._exit(0)

